#include <string>
using namespace std;

class Solution {
public:
    bool isPrime(int x) {
        if (x < 2) return false;
        if (x == 2 || x == 3) return true;
        if (x % 2 == 0 || x % 3 == 0) return false;
        for (int d = 5; d * d <= x; d += 6) {
            if (x % d == 0 || x % (d + 2) == 0) return false;
        }
        return true;
    }

    bool isCompletePrime(int num) {
        if (!isPrime(num)) return false;
        string s = to_string(num);
        if (s.length() == 1) return true;
        for (int i = 0; i < (int)s.length(); i++) {
            string reduced = s.substr(0, i) + s.substr(i + 1);
            if (reduced.empty() || !isPrime(stoi(reduced))) return false;
        }
        return true;
    }
};

class Solution {
    private boolean isPrime(int x) {
        if (x < 2) return false;
        if (x == 2 || x == 3) return true;
        if (x % 2 == 0 || x % 3 == 0) return false;
        for (int d = 5; d * d <= x; d += 6) {
            if (x % d == 0 || x % (d + 2) == 0) return false;
        }
        return true;
    }

    public boolean isCompletePrime(int num) {
        if (!isPrime(num)) return false;
        String s = String.valueOf(num);
        if (s.length() == 1) return true;
        for (int i = 0; i < s.length(); i++) {
            String reduced = s.substring(0, i) + s.substring(i + 1);
            if (reduced.isEmpty() || !isPrime(Integer.parseInt(reduced))) return false;
        }
        return true;
    }
}

